<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { api } from '../api/client'
import AppShell from '../components/AppShell.vue'
import StatusPill from '../components/StatusPill.vue'
import type { BillingRecord, CreditRequest, Paginated, ReferenceData } from '../types/api'
import { apiError, money } from '../utils/format'

interface AdminForm { admin_branch: string; admin_dept: string; admin_project: string; admin_discount_final: number; bplus_salesman_code: string; bplus_sale_type_code: string; credit_limit: number; credit_outstanding: number; credit_term: number; requested_credit_term: number; items: Array<Record<string, string | number | null>> }
const bills = ref<BillingRecord[]>([]); const credits = ref<CreditRequest[]>([]); const creditPage = ref<Paginated<CreditRequest> | null>(null); const refs = ref<ReferenceData | null>(null); const error = ref(''); const message = ref(''); const forms = reactive<Record<number, AdminForm>>({}); const creditForms = reactive<Record<number, { ar_code: string; ar_name: string; credit_limit: number; credit_term: number }>>({})
async function load(page = creditPage.value?.current_page || 1) {
  try {
    const [billResponse, creditResponse, referenceResponse] = await Promise.all([api.get<{ data: BillingRecord[] }>('/api/v1/bills/admin-queue'), api.get<Paginated<CreditRequest>>('/api/v1/credit-requests', { params: { status: 'อนุมัติวงเงินแล้ว', page, per_page: 20 } }), api.get<{ data: ReferenceData }>('/api/v1/reference-data')])
    bills.value = billResponse.data.data; creditPage.value = creditResponse.data; credits.value = creditResponse.data.data; refs.value = referenceResponse.data.data
    bills.value.forEach((bill) => { forms[bill.bill_id] = { admin_branch: bill.admin_branch || 'VH000', admin_dept: bill.admin_dept || 'VH000', admin_project: bill.admin_project || 'VH000', admin_discount_final: Number(bill.admin_discount_final || 0), bplus_salesman_code: bill.bplus_salesman_code || '', bplus_sale_type_code: bill.bplus_sale_type_code || 'สินเชื่อ', credit_limit: Number(bill.credit_limit || 0), credit_outstanding: Number(bill.credit_outstanding || 0), credit_term: Number(bill.credit_term || 0), requested_credit_term: Number(bill.requested_credit_term || bill.credit_term || 0), items: (bill.items || []).map((item) => ({ item_id: item.item_id, admin_lot: item.admin_lot || '', admin_serial: item.admin_serial || '', admin_storage: item.admin_storage || '', admin_free_qty: item.admin_free_qty || 0, admin_disocount_unit: item.admin_disocount_unit || 0, admin_weight_unit: item.admin_weight_unit || 0 })) } })
    credits.value.forEach((request) => { creditForms[request.request_id] = { ar_code: request.ar_code || '', ar_name: request.ar_name || request.company_name, credit_limit: Number(request.requested_credit_limit), credit_term: request.requested_credit_term } })
  } catch (cause) { error.value = apiError(cause) }
}
async function openCredit(request: CreditRequest) { try { await api.post(`/api/v1/credit-requests/${request.request_id}/open`, creditForms[request.request_id]); message.value = `เปิดวงเงินคำขอ #${request.request_id} แล้ว`; await load() } catch (cause) { error.value = apiError(cause) } }
async function prepare(bill: BillingRecord) { try { await api.post(`/api/v1/bills/${bill.bill_id}/prepare`, forms[bill.bill_id]); message.value = `บันทึก Bplus และส่งบิล #${bill.bill_id} ไปเตรียม Export แล้ว`; await load() } catch (cause) { error.value = apiError(cause) } }
const creditRemain = (billId: number) => Math.max(forms[billId].credit_limit - forms[billId].credit_outstanding, 0)
const creditRisk = (bill: BillingRecord) => {
  const limit = forms[bill.bill_id].credit_limit
  const afterBill = creditRemain(bill.bill_id) - Number(bill.total_amount || 0)
  if (limit <= 0 || afterBill < 0) return { className: 'risk-banner--danger', text: `เครดิตเสี่ยงสูง: หลังเปิดบิลเกินวงเงิน ${money(Math.abs(afterBill))}` }
  if (afterBill / limit < .2) return { className: 'risk-banner--warning', text: `เครดิตเสี่ยงน้อย: หลังเปิดบิลเหลือ ${money(afterBill)} (${Math.round(afterBill / limit * 100)}%)` }
  return { className: 'risk-banner--success', text: `เครดิตผ่าน: หลังเปิดบิลเหลือ ${money(afterBill)} (${Math.round(afterBill / limit * 100)}%)` }
}
onMounted(load)
</script>
<template>
  <AppShell title="รายการบิลรอพิมพ์ & จัดทำข้อมูล" subtitle="ตรวจรหัสลูกหนี้ เติมข้อมูล Bplus, เครดิต และคลังสินค้าก่อนส่งออก">
    <p v-if="error" class="form-error">{{ error }}</p><p v-if="message" class="success-message">{{ message }}</p>
    <section><div class="section-heading"><h2>คำขอวงเงินที่หัวหน้าอนุมัติแล้ว</h2><span class="count-badge">{{ creditPage?.total || 0 }}</span></div><div class="list-stack"><form v-for="request in credits" :key="request.request_id" class="content-card form-grid" @submit.prevent="openCredit(request)"><div class="span-2 section-heading"><div><h2>#{{ request.request_id }} · {{ request.company_name }}</h2><p>{{ request.request_type === 'change_existing' ? 'แก้ไขวงเงินเดิม' : 'เปิดวงเงินใหม่' }} · อนุมัติโดย {{ request.approved_by }}</p></div><StatusPill :status="request.status" /></div><div class="span-2 detail-grid"><p><span>วงเงินเดิม</span><strong>{{ money(request.current_credit_limit) }}</strong></p><p><span>วงเงินที่อนุมัติ</span><strong>{{ money(request.requested_credit_limit) }}</strong></p><p><span>Term เดิม</span><strong>{{ request.current_credit_term || 0 }} วัน</strong></p><p><span>Term ที่อนุมัติ</span><strong>{{ request.requested_credit_term }} วัน</strong></p><p><span>ผู้ขอ</span><strong>{{ request.created_by || '-' }}</strong></p><p><span>เหตุผล</span><strong>{{ request.justification || '-' }}</strong></p></div><label><span>รหัสลูกหนี้ Bplus *</span><input v-model="creditForms[request.request_id].ar_code" required></label><label><span>ชื่อลูกหนี้ *</span><input v-model="creditForms[request.request_id].ar_name" required></label><label><span>วงเงินเครดิต</span><input v-model.number="creditForms[request.request_id].credit_limit" type="number" min="1" required></label><label><span>Credit Term</span><input v-model.number="creditForms[request.request_id].credit_term" type="number" min="1" required></label><button class="primary-button span-2">บันทึกวงเงินเข้าระบบ</button></form><div v-if="credits.length === 0" class="content-card empty-state">ไม่มีคำขอวงเงินรอ Admin</div></div><div v-if="creditPage && creditPage.last_page > 1" class="pagination"><span>คำขอ {{ creditPage.from || 0 }}–{{ creditPage.to || 0 }} จาก {{ creditPage.total }}</span><div><button class="secondary-button" :disabled="!creditPage.prev_page_url" @click="load(creditPage.current_page - 1)">ก่อนหน้า</button><span>หน้า {{ creditPage.current_page }} / {{ creditPage.last_page }}</span><button class="secondary-button" :disabled="!creditPage.next_page_url" @click="load(creditPage.current_page + 1)">ถัดไป</button></div></div></section>
    <section class="section-gap"><div class="section-heading"><h2>คิวบิลรอ Admin</h2><span class="count-badge">{{ bills.length }}</span></div><div class="metrics-grid metrics-grid--three"><article class="metric-card"><span>บิลรอกรอกข้อมูล</span><strong>{{ bills.length }}</strong></article><article class="metric-card metric-card--primary"><span>มูลค่ารวม</span><strong class="metric-money">{{ money(bills.reduce((sum, bill) => sum + Number(bill.total_amount || 0), 0)) }}</strong></article><article class="metric-card"><span>สถานะระบบ</span><strong>พร้อม</strong></article></div>
      <div class="list-stack"><form v-for="bill in bills" :key="bill.bill_id" class="content-card form-grid" @submit.prevent="prepare(bill)"><div class="span-2 section-heading"><div><h2>บิล #{{ bill.bill_id }} · {{ bill.buyer_name }}</h2><p>Sale: {{ bill.created_by }} · จังหวัด {{ bill.province || '-' }} · {{ money(bill.total_amount) }}</p><p :class="bill.tax_info_filled ? 'success-message' : 'muted'">{{ bill.tax_info_filled ? 'ลูกค้ายืนยันและพิมพ์ข้อมูลภาษีแล้ว' : 'รอลูกค้ายืนยันข้อมูลผ่าน Customer Portal' }}</p></div><StatusPill :status="bill.status" /></div>
        <label><span>รหัสลูกหนี้ Bplus</span><input :value="bill.bplus_customer_code || bill.tax_id || ''" disabled></label><label><span>รหัสพนักงานขาย Bplus *</span><select v-model="forms[bill.bill_id].bplus_salesman_code" required><option value="">-- เลือก --</option><option v-for="sale in refs?.salesmen" :key="sale.salesman_code" :value="sale.salesman_code">{{ sale.salesman_code }} | {{ sale.salesman_name }}</option></select></label><label><span>รหัสซื้อขาย</span><select v-model="forms[bill.bill_id].bplus_sale_type_code"><option>สินเชื่อ</option><option>เงินสด</option><option>ผ่อนชำระ</option></select></label><label><span>รหัสสาขา</span><select v-model="forms[bill.bill_id].admin_branch"><option v-for="code in ['VH000','VH001','VH002','VH003','VH004','VH005']" :key="code">{{ code }}</option></select></label><label><span>รหัสแผนก</span><select v-model="forms[bill.bill_id].admin_dept"><option v-for="code in ['VH000','VH001','VH002','VH003','VH004','VH005']" :key="code">{{ code }}</option></select></label><label><span>รหัสโครงการ</span><select v-model="forms[bill.bill_id].admin_project"><option v-for="code in ['VH000','VH001','VH002','VH003','VH004','VH005']" :key="code">{{ code }}</option></select></label><label><span>ส่วนลดท้ายบิล Admin</span><input v-model.number="forms[bill.bill_id].admin_discount_final" type="number" min="0"></label>
        <div class="span-2 detail-grid"><label><span>วงเงินเครดิต</span><input v-model.number="forms[bill.bill_id].credit_limit" type="number" min="0"></label><label><span>เครดิตค้างชำระ</span><input v-model.number="forms[bill.bill_id].credit_outstanding" type="number" min="0"></label><p><span>เครดิตคงเหลือ</span><strong>{{ money(creditRemain(bill.bill_id)) }}</strong></p><label><span>Term ระบบ</span><input v-model.number="forms[bill.bill_id].credit_term" type="number" min="0"></label><label><span>Term ที่ขอ</span><input v-model.number="forms[bill.bill_id].requested_credit_term" type="number" min="0"></label></div><p class="span-2 risk-banner" :class="creditRisk(bill).className">{{ creditRisk(bill).text }}</p>
        <div class="span-2 form-section-block"><h2>ข้อมูลคลังสินค้าแยกตามรายการ</h2><article v-for="(item, index) in bill.items" :key="item.item_id" class="warehouse-item"><div><strong>{{ item.main_category }} · {{ item.sub_category }}</strong><small>{{ item.quantity }} {{ item.unit_type }} · {{ money(item.unit_price) }}</small></div><label><span>Lot</span><input v-model="forms[bill.bill_id].items[index].admin_lot"></label><label><span>Serial</span><input v-model="forms[bill.bill_id].items[index].admin_serial"></label><label><span>ตำแหน่งเก็บ</span><select v-model="forms[bill.bill_id].items[index].admin_storage"><option value=""></option><option>WH-MAIN</option><option>WH-TEMP</option></select></label><label><span>แถม</span><input v-model.number="forms[bill.bill_id].items[index].admin_free_qty" type="number" min="0"></label><label><span>ส่วนลด/หน่วย</span><input v-model.number="forms[bill.bill_id].items[index].admin_disocount_unit" type="number" min="0"></label><label><span>น้ำหนัก/หน่วย</span><input v-model.number="forms[bill.bill_id].items[index].admin_weight_unit" type="number" min="0"></label></article></div><button class="primary-button span-2">บันทึกข้อมูล Bplus และอนุมัติส่งออก</button>
      </form><div v-if="bills.length === 0" class="content-card empty-state">ไม่มีบิลค้างในคิว</div></div>
    </section>
  </AppShell>
</template>
